package counter

// Package-level globals — refactor these into a Counter struct.
var count int
var step int = 1

// Increment adds step to the counter.
func Increment() {
	count += step
}

// Decrement subtracts step from the counter.
func Decrement() {
	count -= step
}

// Reset sets the counter back to zero.
func Reset() {
	count = 0
}

// Value returns the current counter value.
func Value() int {
	return count
}

// SetStep changes the increment/decrement step size.
func SetStep(s int) {
	step = s
}

