package counter

import "testing"

func TestCounterBasic(t *testing.T) {
	c := NewCounter(1)
	c.Increment()
	c.Increment()
	if c.Value() != 2 {
		t.Errorf("want 2, got %d", c.Value())
	}
	c.Decrement()
	if c.Value() != 1 {
		t.Errorf("want 1 after decrement, got %d", c.Value())
	}
	c.Reset()
	if c.Value() != 0 {
		t.Errorf("want 0 after reset, got %d", c.Value())
	}
}

func TestCounterStep(t *testing.T) {
	c := NewCounter(5)
	c.Increment()
	if c.Value() != 5 {
		t.Errorf("want 5 with step=5, got %d", c.Value())
	}
	c.Decrement()
	if c.Value() != 0 {
		t.Errorf("want 0 after decrement with step=5, got %d", c.Value())
	}
}

func TestCounterIsolation(t *testing.T) {
	c1 := NewCounter(1)
	c2 := NewCounter(1)
	c1.Increment()
	c1.Increment()
	if c2.Value() != 0 {
		t.Errorf("counters should be independent: c2=%d, want 0", c2.Value())
	}
}
